import XCTest
@testable import DroboKern

/// Echte Rohantworten aus der IORegistry einer Drobo 5C (Dext 3.6, Property DroboStatus); Seriennummern (vpd80, Laufwerke) und der nicht gedeutete
/// Rest von Seite 0x08 sind durch Dummys ersetzt (oeffentliches Repo).
enum DroboFixture {
    static let hex: [String: String] = [
        "inquiry": "000000025c00000044726f626f0000003543000047656e330000000042383130352e3030",
        "p3A_01": "7a010018050d10000000200000000000000000000000000100000000",
        "p3A_02": "7a020038000003dd8600f000000039ca9f3f100000003da8254000000000000000000000",
        "p3A_06": "7a060002000b",
        "p3A_08": "",
        "p3A_09": "7a09001000028004000000000000000000000000ffff",
        "p3A_33": "7a33001014000100000a7c2e0000002d00000000312c",
        "p3A_35": "",
        "vpd80": "0080001844554d4d5953455249414c30303031000000000000000000",
    ]
    static func dict(zeit: Double = 1792151779) -> [String: Any] {
        var d: [String: Any] = ["zeit": NSNumber(value: zeit), "ok": true, "fehler": "keine"]
        for (k, h) in hex { d[k] = Data(stride(from: 0, to: h.count, by: 2).map { UInt8(h[h.index(h.startIndex, offsetBy: $0)..<h.index(h.startIndex, offsetBy: $0 + 2)], radix: 16)! }) }
        return d
    }
}
